package com.sakalti.modifier;
import net.minecraft.world.entity.item.ItemEntity; import net.minecraft.world.entity.LivingEntity; import net.minecraft.world.level.Level; import net.minecraft.world.phys.Vec3; import net.minecraft.world.item.ItemStack;
import slimeknights.tconstruct.library.modifiers.Modifier; import slimeknights.tconstruct.library.tools.nbt.IToolStackView;
public class SuperMagnetModifier extends Modifier { @Override public void onInventoryTick(IToolStackView tool,int level,Level world,LivingEntity e,int slot,boolean selected,boolean correct,ItemStack stack){if(world==null||world.isClientSide||e==null||!correct)return;for(ItemEntity item:world.getEntitiesOfClass(ItemEntity.class,e.getBoundingBox().inflate(6),x->!x.hasPickUpDelay())){Vec3 d=e.position().add(0,e.getEyeHeight()/2.0,0).subtract(item.position());double len=d.length();if(len>0.5&&len<6){double s=0.5*level/len;item.setDeltaMovement(item.getDeltaMovement().add(d.scale(s)));}}}}
